{"implementation": "import math
def solve(case):
    matrix = case['matrix']
    if not matrix or not all(isinstance(row, list) for row in matrix):
        raise ValueError('Matrix must be a nonempty list of lists')
    n_rows = len(matrix)
    if n_rows == 0:
        raise ValueError('Matrix must have at least one row')
    n_cols = len(matrix[0])
    for row in matrix:
        if len(row) != n_cols:
            raise ValueError('Matrix must be rectangular')
    # compute document frequency per feature (column)
    df = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    # compute idf
    idf = [0.0] * n_cols
    for j in range(n_cols):
        idf[j] = math.log(1.0 + n_rows / (1.0 + df[j]))
    # compute weighted matrix and row_degree
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = []
        row_sum = 0.0
        for j, val in enumerate(row):
            w = val * idf[j]
            weighted_row.append(w)
            row_sum += w
        weighted_matrix.append(weighted_row)
        row_degree.append(row_sum)
    # return as JSON-serializable dict
    return {
        'idf': idf,
        'row_degree': row_degree,
        'weighted_matrix': weighted_matrix
    }
"}
